cases.bad:
// offscreen: write debug info directly — silently fails
chrome.storage.local.set({ __ocrScriptLoaded: true, __ocrStep: 'init' });
// content script reads — always undefined
chrome.storage.local.get('__ocrScriptLoaded', (r) => {
  console.log(r.__ocrScriptLoaded); // undefined
});

cases.good:
// offscreen: send debug via sendMessage to background
chrome.runtime.sendMessage({
  type: 'OFFSCREEN_DEBUG_LOG',
  data: { kind: 'script-loaded', step: 'init', time: Date.now() }
}).catch(() => {});
// background: receives and writes to chrome.storage.local (works in SW context)
chrome.runtime.onMessage.addListener((msg) => {
  if (msg.type === 'OFFSCREEN_DEBUG_LOG') {
    chrome.storage.local.set({ __offscreenDebugLog: msg.data });
  }
});
